/* @lc app=leetcode id=1719 lang=kotlin */ class Solution { fun checkWays(pairs: Array<IntArray>): Int = pairs.flatMap { listOf(it[0] to it[1], it[1] to it[0]) }.groupBy({ it.first }, { it.second }).mapValues { it.value.toSet() }.let { adj -> adj.keys.sortedByDescending { adj[it]!!.size }.let { ord -> if (adj[ord[0]]!!.size != ord.size - 1) 0 else ord.drop(1).fold(1) { res, u -> if (res == 0) 0 else adj[u]!!.filter { adj[it]!!.size >= adj[u]!!.size }.minByOrNull { adj[it]!!.size }.let { par -> if (par == null || !(adj[u]!! - par).all { it in adj[par]!! }) 0 else if (adj[par]!!.size == adj[u]!!.size) 2 else res } } } } }